# صورة الحرف في الكلمة: أ إ آ ↔ ألف/همزة · ئ ؤ ↔ همزة · ى ↔ ياء
def glyphs(w):
    """حروف الكلمة (هيكلها) مردودة إلى مفاتيح LETTERS — الألف بأشكالها تُعدّ «ا»، والهمزة على نبرة/واو تُعدّ «ء»."""
    out = []
    for ch in skel(w):
        if ch in 'أإآٱ': out.append('ا')
        elif ch in 'ئؤ': out.append('ء')
        elif ch == 'ى': out.append('ي')
        elif ch in LETTERS: out.append(ch)
    return out
