# حروف كلّ حلقة (الجديدة) — بالترتيب
NEW = {
 'U01L01': list('ابتثني'), 'U01L02': [], 'U01L03': list('جحخدذ'), 'U01L04': list('رزملك'), 'U01L05': ['ة'], 'U01L06': [], 'U01L07': [],
 'U02L01': list('سشصض'), 'U02L02': list('طظعغ'), 'U02L03': list('فقهو'), 'U02L04': ['ء'], 'U02L05': [], 'U02L06': [], 'U02L07': [],
}
ORDER = ['U01L01', 'U01L02', 'U01L03', 'U01L04', 'U01L05', 'U01L06', 'U01L07', 'U02L01', 'U02L02', 'U02L03', 'U02L04', 'U02L05', 'U02L06', 'U02L07']
def known(key):
    """الحروف المعروفة حتى هذه الحلقة (شاملة)."""
    out = []
    for k in ORDER:
        out += NEW[k]
        if k == key: break
    return out
def check_words():
    bad = []
    for key, ws in W.items():
        kn = set(known(key))
        for w, img in ws:
            extra = [g for g in glyphs(w) if g not in kn]
            if extra: bad.append((key, w, extra))
    return bad
